import pandas as pd
import numpy as np

DATASET_PATH = 'chunks_csv/cyclehire_w000.csv'
ADJACENCY_PATH = 'chunks_csv/borough_adjacency.csv'

# Step 1: Compute self-containment ratios
df = pd.read_csv(DATASET_PATH)
borough_departures = df.groupby('StartBorough').size()
borough_self_contained = df.groupby('StartBorough').apply(lambda x: (x['StartBorough'] == x['EndBorough']).sum())
ratios = (borough_self_contained / borough_departures).to_dict()

# Step 2: Build neighbor map
adj_df = pd.read_csv(ADJACENCY_PATH)
neighbor_map = {}
for _, row in adj_df.iterrows():
    b = row['borough']
    n = row['neighbor']
    if b not in neighbor_map:
        neighbor_map[b] = []
    neighbor_map[b].append(n)

# Step 3: Compute avg neighbor ratios
borough_ratios = {}
for b in ratios:
    neighbors = neighbor_map.get(b, [])
    neighbor_ratios = [ratios[n] for n in neighbors if n in ratios]
    if neighbor_ratios:
        avg_neighbor = sum(neighbor_ratios) / len(neighbor_ratios)
    else:
        avg_neighbor = 0
    borough_ratios[b] = {
        'ratio': ratios[b],
        'avg_neighbor_ratio': avg_neighbor
    }

# Step 4: Compute overall mean ratio
mean_ratio = sum(ratios.values()) / len(ratios)

# Step 5: Permutation test
boroughs = list(ratios.keys())
values = np.array([ratios[b] for b in boroughs])

observed_products = {}
for b in boroughs:
    neighbors = neighbor_map.get(b, [])
    if not neighbors:
        continue
    neighbor_ratios = [ratios[n] for n in neighbors if n in ratios]
    if neighbor_ratios:
        avg_neighbor = sum(neighbor_ratios) / len(neighbor_ratios)
    else:
        avg_neighbor = 0
    product = ratios[b] * avg_neighbor
    observed_products[b] = product

num_permutations = 500
permuted_products = {b: [] for b in boroughs}

for _ in range(num_permutations):
    shuffled_values = np.random.permutation(values)
    shuffled_ratios = {boroughs[i]: shuffled_values[i] for i in range(len(boroughs))}

    for b in boroughs:
        neighbors = neighbor_map.get(b, [])
        if not neighbors:
            continue
        neighbor_shuffled = [shuffled_ratios[n] for n in neighbors if n in shuffled_ratios]
        if neighbor_shuffled:
            avg_neighbor = sum(neighbor_shuffled) / len(neighbor_shuffled)
        else:
            avg_neighbor = 0
        product = shuffled_ratios[b] * avg_neighbor
        permuted_products[b].append(product)

# Step 6: Identify hot and cold spots
hot_spots = []
cold_spots = []

for b in boroughs:
    if b not in observed_products:
        continue  # skip boroughs with no neighbors
    observed = observed_products[b]
    permuted = permuted_products[b]
    if observed > 0:
        upper_count = sum(1 for p in permuted if p >= observed)
        upper_p = upper_count / num_permutations
        if upper_p < 0.05:
            if borough_ratios[b]['ratio'] > mean_ratio and borough_ratios[b]['avg_neighbor_ratio'] > mean_ratio:
                hot_spots.append((b, observed, upper_p))
    else:
        lower_count = sum(1 for p in permuted if p <= observed)
        lower_p = lower_count / num_permutations
        if lower_p < 0.05:
            if borough_ratios[b]['ratio'] < mean_ratio and borough_ratios[b]['avg_neighbor_ratio'] < mean_ratio:
                cold_spots.append((b, observed, lower_p))

# Step 7: Print final answer
results = []
for b, obs, p in hot_spots:
    results.append(f"{b} (HH, statistical method={p})")
for b, obs, p in cold_spots:
    results.append(f"{b} (LL, statistical method={p})")
print("FINAL ANSWER: " + ", ".join(results))
